60|// Strict parse at the trust boundary: exact fields only, so a client
61|// bug cannot silently spend budget on a misread request.
62|export function parseImageRequest(json: unknown): ImageRequest {
63|  if (!isRecord(json)) throw new ImageValidationError();
64|  const { kind } = json;
65|  if (kind === "passage") {
66|    const keys = Object.keys(json).sort().join(",");
67|    if (keys !== "bookId,kind,n,textVersion") throw new ImageValidationError();
68|    if (typeof json.bookId !== "string" || json.bookId.length === 0) throw new ImageValidationError();
69|    if (typeof json.textVersion !== "string" || json.textVersion.length === 0) {
70|      throw new ImageValidationError();
71|    }
72|    if (typeof json.n !== "number" || !Number.isInteger(json.n)) throw new ImageValidationError();
73|    return { kind: "passage", bookId: json.bookId, textVersion: json.textVersion, n: json.n };
74|  }
75|  if (kind === "scene") {
76|    const keys = Object.keys(json).sort().join(",");
77|    if (keys !== "bookId,kind,sceneId,textVersion") throw new ImageValidationError();
78|    if (typeof json.bookId !== "string" || json.bookId.length === 0) throw new ImageValidationError();
79|    if (typeof json.textVersion !== "string" || json.textVersion.length === 0) {
80|      throw new ImageValidationError();
81|    }
82|    if (typeof json.sceneId !== "string" || json.sceneId.length === 0) throw new ImageValidationError();
83|    return { kind: "scene", bookId: json.bookId, textVersion: json.textVersion, sceneId: json.sceneId };
84|  }
85|  throw new ImageValidationError();
