1|// CLI: npm run build:book -- oz [--step ingest|segment|classify|resplit|cluster] [--force] [--dry-run]
2|// --dry-run prints one freshness line per selected step and stops before
3|// any client, write, or network call.
4|import { readFileSync } from "node:fs";
5|import { join } from "node:path";
6|import { runClassify } from "./classify";
7|import { runCluster } from "./cluster-tracks";
8|import { bookConfig, runIngest } from "./ingest";
9|import type { StepCtx } from "./ingest";
10|import { planSteps } from "./freshness";
11|import type { FreshStep } from "./freshness";
12|import { createJevClient } from "./jev";
13|import { createMetaClient } from "./meta";
14|import { runResplit } from "./resplit";
15|import { runSegment } from "./segment";
16|
17|const STEPS = ["ingest", "segment", "classify", "resplit", "cluster"] as const;
18|
19|function loadEnv(): void {
20|  try {
21|    if (typeof process.loadEnvFile === "function") process.loadEnvFile(".env.local");
22|  } catch {
23|    // No .env.local is fine; env may come from elsewhere.
24|  }
25|}
26|
27|function env(name: string, fallback?: string): string {
28|  const value = process.env[name] ?? fallback;
29|  if (value === undefined || value === "") throw new Error(`${name} is not set`);
30|  return value;
31|}
32|
33|async function main(): Promise<void> {
34|  loadEnv();
35|  const args = process.argv.slice(2);
36|  const bookKey = args.find((a) => !a.startsWith("--")) ?? "";
37|  const stepFlag = args.indexOf("--step");
38|  const stepArg = stepFlag === -1 ? undefined : args[stepFlag + 1];
39|  const force = args.includes("--force");
40|  const dryRun = args.includes("--dry-run");
41|  if (!bookKey) throw new Error("usage: build:book <book> [--step ingest|segment|classify|resplit|cluster] [--force] [--dry-run]");
42|  bookConfig(bookKey); // fails fast on unknown keys with the valid list
43|  const only = stepArg ?? "";
44|  if (only !== "" && !(STEPS as readonly string[]).includes(only)) {
45|    throw new Error(`unknown step "${only}", valid steps: ${STEPS.join(", ")}`);
46|  }
47|  const ctx: StepCtx = { bookKey, force, dir: join("data", "books", bookKey) };
48|  if (dryRun) {
49|    const selected = (only === "" ? [...STEPS] : [only]) as (typeof STEPS)[number][];
50|    if (selected.includes("ingest")) console.log("ingest: not checked in dry run (frozen textVersion rule)");
51|    for (const plan of planSteps(ctx.dir, selected.filter((s): s is FreshStep => s !== "ingest"), force)) {
52|      console.log(`${plan.step}: ${plan.reuse ? "reuse" : "redo"} (${plan.reason})`);
53|    }
54|    return;
55|  }
56|  const run: Record<(typeof STEPS)[number], boolean> = {
57|    ingest: only === "" || only === "ingest",
58|    segment: only === "" || only === "segment",
59|    classify: only === "" || only === "classify",
60|    resplit: only === "" || only === "resplit",
61|    cluster: only === "" || only === "cluster",
62|  };
63|  if (run.ingest) {
64|    const book = await runIngest(ctx);
65|    console.log(`ingest: ${book.chapters.length} chapters, ${book.paragraphs.length} paragraphs, ${book.textVersion}`);
66|  }
67|  if (run.segment) {
68|    const meta = createMetaClient({ apiKey: env("META_API_KEY"), model: process.env.META_MODEL ?? "muse-spark-1.3-contributor" });
69|    console.log(`segment: ${meta.model}`);
70|    const scenes = await runSegment(ctx, { meta });
71|    console.log(`segment: ${scenes.length} scenes`);
72|  }
73|  if (run.classify) {
74|    const meta = createMetaClient({ apiKey: env("META_API_KEY"), model: process.env.META_MODEL ?? "muse-spark-1.3-contributor" });
75|    const jev = createJevClient({ apiKey: env("JEV_API_KEY"), model: process.env.JEV_MODEL ?? "jev-1.14.0" });
76|    const scenes = await runClassify(ctx, { jev, meta });
77|    const overrides = scenes.filter((s) => s.muse_override !== null).length;
78|    const failures = scenes.filter((s) => s.final === null).length;
79|    console.log(`classify: ${scenes.length} scenes, ${overrides} overrides, ${failures} failures`);
80|  }
81|  if (run.resplit) {
82|    const meta = createMetaClient({ apiKey: env("META_API_KEY"), model: process.env.META_MODEL ?? "muse-spark-1.3-contributor" });
83|    const jev = createJevClient({ apiKey: env("JEV_API_KEY"), model: process.env.JEV_MODEL ?? "jev-1.14.0" });
84|    const scenes = await runResplit(ctx, { jev, meta });
85|    console.log(`resplit: ${scenes.length} scenes`);
86|  }
87|  if (run.cluster) {
88|    await runCluster(ctx);
89|    console.log("cluster: wrote music-clusters.json");
90|  }
91|  printSummary(ctx.dir);
92|}
93|
94|function printSummary(dir: string): void {
95|  const book = JSON.parse(readFileSync(join(dir, "book.json"), "utf8")) as {
96|    chapters: unknown[];
97|    paragraphs: unknown[];
98|  };
99|  let scenes: { final: { vector: Record<string, number> } | null }[] = [];
100|  let overrideRate = 0;
101|  let jev = { cost_usd: 0 };
102|  let meta = { cost_usd: 0 };
103|  let total = 0;
104|  try {
105|    const analysis = JSON.parse(readFileSync(join(dir, "analysis.json"), "utf8")) as {
106|      scenes: (typeof scenes)[number][];
107|      override_rate: number;
108|      provenance: { jev: typeof jev; meta: typeof meta; total_cost_usd: number };
109|    };
110|    scenes = analysis.scenes;
111|    overrideRate = analysis.override_rate;
112|    jev = analysis.provenance.jev;
113|    meta = analysis.provenance.meta;
114|    total = analysis.provenance.total_cost_usd;
115|  } catch {
116|    // Steps after ingest may not have run yet.
117|  }
118|  const dist = new Map<string, number>();
119|  let failures = 0;
120|  for (const scene of scenes) {
121|    if (!scene.final) {
122|      failures += 1;
123|      continue;
124|    }
125|    const top = Object.entries(scene.final.vector).sort((a, b) => b[1] - a[1])[0]?.[0] ?? "?";
126|    dist.set(top, (dist.get(top) ?? 0) + 1);
127|  }
128|  console.log(`summary: ${book.chapters.length} chapters, ${book.paragraphs.length} paragraphs, ${scenes.length} scenes`);
129|  console.log(`emotions: ${[...dist.entries()].map(([id, count]) => `${id} ${count}`).join(", ") || "none yet"}`);
130|  console.log(`override rate ${((overrideRate ?? 0) * 100).toFixed(1)}%, failures ${failures}`);
131|  console.log(`cost: jev $${(jev.cost_usd ?? 0).toFixed(4)}, meta $${(meta.cost_usd ?? 0).toFixed(4)}, total $${(total ?? 0).toFixed(4)}`);
132|}
133|
134|main().catch((error: unknown) => {
135|  console.error(`error: ${(error as Error).message}`);
136|  process.exit(1);
137|});

Read text file `pipeline/freshness.ts`.
1|// One freshness rule per pipeline step: each step compares the
2|// fingerprint of its real input against the key its last run recorded.
3|// Reuse only when the keys match and --force is off.
4|import { createHash } from "node:crypto";
5|import { readFileSync } from "node:fs";
6|import { join } from "node:path";
7|
8|export function fingerprint(value: unknown): string {
9|  return createHash("sha256").update(JSON.stringify(value)).digest("hex").slice(0, 16);
10|}
11|
12|export interface StepKeys {
13|  recorded: string | undefined;
14|  current: string;
15|}
16|
17|export interface FreshnessDecision {
18|  reuse: boolean;
19|  reason: string;
20|}
21|
22|export function decide(force: boolean, recorded: string | undefined, current: string): FreshnessDecision {
23|  if (force) return { reuse: false, reason: "forced" };
24|  if (recorded === undefined) return { reuse: false, reason: "no previous output" };
25|  if (recorded === current) return { reuse: true, reason: "inputs unchanged" };
26|  return { reuse: false, reason: "inputs changed" };
27|}
28|
29|function readJson(path: string): unknown {
30|  try {
31|    return JSON.parse(readFileSync(path, "utf8"));
32|  } catch {
33|    return undefined;
34|  }
35|}
36|
37|function asRecord(value: unknown): Record<string, unknown> {
38|  return typeof value === "object" && value !== null ? (value as Record<string, unknown>) : {};
39|}
40|
41|function asString(value: unknown): string | undefined {
42|  return typeof value === "string" ? value : undefined;
43|}
44|
45|export function classifyInputOf(
46|  scenes: { id: unknown; ch: unknown; start_n: unknown; end_n: unknown; title: unknown; summary: unknown; characters: unknown }[],
47|  textVersion: unknown,
48|): string {
49|  return fingerprint({
50|    textVersion,
51|    scenes: scenes.map((s) => ({ id: s.id, ch: s.ch, start_n: s.start_n, end_n: s.end_n, title: s.title, summary: s.summary, characters: s.characters })),
52|  });
53|}
54|
55|export function resplitInputOf(scenes: { id: unknown; start_n: unknown; end_n: unknown }[], textVersion: unknown): string {
56|  return fingerprint({ textVersion, scenes: scenes.map((s) => ({ id: s.id, start_n: s.start_n, end_n: s.end_n })) });
57|}
58|
59|export function clusterInputOf(scenes: { id: unknown; final: unknown }[]): string {
60|  return fingerprint(scenes.map((s) => ({ id: s.id, final: s.final })));
61|}
62|
63|export function segmentKeys(dir: string): StepKeys {
64|  const book = asRecord(readJson(join(dir, "book.json")));
65|  const scenes = asRecord(readJson(join(dir, "scenes.json")));
66|  return { recorded: asString(scenes.textVersion), current: asString(book.textVersion) ?? "" };
67|}
68|
69|export function classifyKeys(dir: string): StepKeys {
70|  const book = asRecord(readJson(join(dir, "book.json")));
71|  const scenes = asRecord(readJson(join(dir, "scenes.json")));
72|  const analysis = asRecord(readJson(join(dir, "analysis.json")));
73|  const list = Array.isArray(scenes.scenes) ? (scenes.scenes as { id: unknown; ch: unknown; start_n: unknown; end_n: unknown; title: unknown; summary: unknown; characters: unknown }[]) : undefined;
74|  return { recorded: asString(asRecord(analysis.provenance).input), current: list === undefined ? "" : classifyInputOf(list, asString(book.textVersion) ?? "") };
75|}
76|
77|export function resplitKeys(dir: string): StepKeys {
78|  const book = asRecord(readJson(join(dir, "book.json")));
79|  const analysis = asRecord(readJson(join(dir, "analysis.json")));
80|  const list = Array.isArray(analysis.scenes) ? (analysis.scenes as { id: unknown; start_n: unknown; end_n: unknown }[]) : undefined;
81|  return { recorded: asString(asRecord(asRecord(analysis.provenance).resplit).input), current: list === undefined ? "" : resplitInputOf(list, asString(book.textVersion) ?? "") };
82|}
83|
84|export function clusterKeys(dir: string): StepKeys {
85|  const analysis = asRecord(readJson(join(dir, "analysis.json")));
86|  const clusters = asRecord(readJson(join(dir, "music-clusters.json")));
87|  const list = Array.isArray(analysis.scenes) ? (analysis.scenes as { id: unknown; final: unknown }[]) : undefined;
88|  return { recorded: asString(asRecord(clusters.provenance).input), current: list === undefined ? "" : clusterInputOf(list) };
89|}
90|
91|export type FreshStep = "segment" | "classify" | "resplit" | "cluster";
92|
93|const STEP_ORDER: FreshStep[] = ["segment", "classify", "resplit", "cluster"];
94|
95|const STEP_KEYS: Record<FreshStep, (dir: string) => StepKeys> = { segment: segmentKeys, classify: classifyKeys, resplit: resplitKeys, cluster: clusterKeys };
96|
97|export interface StepPlan {
98|  step: FreshStep;
99|  reuse: boolean;
100|  reason: string;
101|}
102|
103|// Plans the selected steps in pipeline order. Once a step would redo,
104|// every later step redoes too, since its input comes from that step.
105|export function planSteps(dir: string, steps: FreshStep[], force: boolean): StepPlan[] {
106|  const wanted = STEP_ORDER.filter((step) => steps.includes(step));
107|  const plans: StepPlan[] = [];
108|  let upstreamRedoes = false;
109|  for (const step of wanted) {
110|    if (upstreamRedoes) {
111|      plans.push({ step, reuse: false, reason: "upstream step redoes" });
112|      continue;
113|    }
114|    const keys = STEP_KEYS[step](dir);
115|    const decision = decide(force, keys.recorded, keys.current);
116|    if (!decision.reuse) upstreamRedoes = true;
117|    plans.push({ step, ...decision });
118|  }
119|  return plans;
120|}

