103|// Plans the selected steps in pipeline order. Once a step would redo,
104|// every later step redoes too, since its input comes from that step.
105|export function planSteps(dir: string, steps: FreshStep[], force: boolean): StepPlan[] {
106|  const wanted = STEP_ORDER.filter((step) => steps.includes(step));
107|  const plans: StepPlan[] = [];
108|  let upstreamRedoes = false;
109|  for (const step of wanted) {
110|    if (upstreamRedoes) {
111|      plans.push({ step, reuse: false, reason: "upstream step redoes" });
112|      continue;
113|    }
114|    const keys = STEP_KEYS[step](dir);
115|    const decision = decide(force, keys.recorded, keys.current);
116|    if (!decision.reuse) upstreamRedoes = true;
117|    plans.push({ step, ...decision });
118|  }
119|  return plans;
