42|// One pass, no skipped steps: hit -> lock -> human -> quota -> budget ->
43|// generate -> store -> index -> release. Every failure after the reserve
44|// refunds quota, budget, and the daily counter and releases the lock.
45|export async function orchestrate(
46|  req: ImageRequest,
47|  deps: OrchestrateDeps,
48|): Promise<ImageResponse> {
49|  const key = imageKey(req);
50|  const indexKey = indexKeyFor(key);
51|  const lockKey = lockKeyFor(key);
52|  // deps.day is the UTC day string (YYYY-MM-DD), shared with quota keys.
53|  const dailyKey = dailySpendKey(deps.day);
54|
55|  const indexed = await deps.kv.get(indexKey);
56|  if (indexed) {
57|    return { status: "ready", url: indexed, cached: true, caption: captionFor(req, deps.content) };
58|  }
59|  const existing = await deps.store.findUrl(key);
60|  if (existing) {
61|    await deps.kv.set(indexKey, existing);
62|    return { status: "ready", url: existing, cached: true, caption: captionFor(req, deps.content) };
63|  }
64|
65|  const token = deps.token ?? randomUUID();
66|  if (!(await deps.kv.setNxEx(lockKey, token, LOCK_TTL_SEC))) return { status: "pending" };
67|
68|  // Best-effort unlock: a release failure must never turn into a client 500.
69|  const release = async (): Promise<void> => {
70|    try {
71|      await deps.kv.releaseIfToken(lockKey, token);
72|    } catch {
73|      // Lock expires on its own; nothing to do.
74|    }
75|  };
76|
77|  const keys = quotaKeysFor({ day: deps.day, ip: deps.ip, salt: deps.env.ipSalt, anonId: deps.anonId });
78|  let quotaTaken = false;
79|  let spendTaken = false;
80|  let dailySpendTaken = false;
81|  // Best-effort refunds that clear their flag only after the write lands,
82|  // so the outer catch refunds each reserve exactly once.
83|  const refundQuotaOnce = async (): Promise<void> => {
84|    try {
85|      await refundQuota(deps.kv, keys);
86|      quotaTaken = false;
87|    } catch {
88|      // Redis down: nothing reserved server-side to retry against.
89|    }
90|  };
91|  const refundSpendOnce = async (): Promise<void> => {
92|    try {
93|      await deps.kv.decrBy(spendKey(), imageCostMicro());
94|      spendTaken = false;
95|    } catch {
96|      // Redis down: nothing reserved server-side to retry against.
97|    }
98|  };
99|  const refundDailySpendOnce = async (): Promise<void> => {
100|    try {
101|      await deps.kv.decrBy(dailyKey, imageCostMicro());
102|      dailySpendTaken = false;
103|    } catch {
104|      // Redis down: nothing reserved server-side to retry against.
105|    }
106|  };
107|
108|  try {
109|    if (!verifyHuman()) {
110|      await release();
111|      return { status: "error", code: "unavailable", message: MSG_FAILED };
112|    }
113|
114|    if (!(await checkQuota(deps.kv, keys)).ok) {
115|      await release();
116|      return { status: "error", code: "quota", message: MSG_QUOTA };
117|    }
118|    quotaTaken = true;
119|
120|    // Both caps apply only to requests paid with our key. The future
121|    // BYOK path must skip these reserves and check its own key instead.
122|    const total = await deps.kv.incrBy(spendKey(), imageCostMicro());
123|    spendTaken = true;
124|    if (budgetExceeded(total, deps.env.spendCapMicro)) {
125|      await refundSpendOnce();
126|      await refundQuotaOnce();
127|      await release();
128|      return { status: "error", code: "budget", message: MSG_CREDITS_OUT };
129|    }
130|
131|    const dailyTotal = await deps.kv.incrBy(dailyKey, imageCostMicro());
132|    dailySpendTaken = true;
133|    // Refresh the expiry on every reserve: cheap, idempotent, and keeps
134|    // the key alive through a busy day without a separate read.
135|    await deps.kv.expire(dailyKey, DAILY_SPEND_TTL_SEC);
136|    if (budgetExceeded(dailyTotal, deps.env.dailySpendCapMicro)) {
137|      await refundDailySpendOnce();
138|      await refundSpendOnce();
139|      await refundQuotaOnce();
140|      await release();
141|      return { status: "error", code: "daily_budget", message: MSG_CREDITS_OUT };
142|    }
