  const output = execFileSync('git', ['cat-file', '-s', ':' + path], {
    encoding: 'utf8',
    stdio: ['ignore', 'pipe', 'ignore'],
  });
  return Number.parseInt(output.trim(), 10);
}

function main() {
  let paths;
  let binaryFlags = new Map();
  try {
    paths = stagedPaths();
    binaryFlags = stagedBinaryFlags();
  } catch {
